use std::{collections::BTreeMap, future::Future};

use serde::{Deserialize, Serialize};

use crate::{BlobId, Error};

/// A monotonic identifier generated by sled, unique within its database.
pub type VersionId = u64;

/// Caller-defined metadata. The registry interprets none of these fields.
pub type Metadata = BTreeMap<String, String>;

/// An object version or a delete marker, returned by both head and list.
#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct RecordMetadata {
    pub key: String,
    pub version_id: VersionId,
    pub blob_id: Option<BlobId>,
    pub metadata: Metadata,
    pub is_delete_marker: bool,
}

/// An exclusive continuation bound, scoped to a prefix and listing mode.
/// Serialization preserves all information required to resume the listing.
#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct Cursor {
    pub(crate) prefix: String,
    pub(crate) include_versions: bool,
    pub(crate) last_key: Vec<u8>,
}

/// A bounded listing with an optional continuation cursor.
#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct PageResult {
    pub records: Vec<RecordMetadata>,
    pub next_cursor: Option<Cursor>,
}

/// The created delete marker or the version requested for deletion.
#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct DeleteResult {
    pub version_id: VersionId,
}

pub trait ObjectRegistry {
    /// Creates a version without checking the blob or interpreting metadata.
    /// Successful mutations await a durable flush. Errors need not mean rollback.
    fn store(
        &self,
        key: &str,
        blob_id: BlobId,
        metadata: Metadata,
    ) -> impl Future<Output = Result<VersionId, Error>> + Send;

    /// Reads the current object, or an explicit non-deleted version/marker.
    /// Each call performs one tree lookup, without a read transaction.
    fn head(
        &self,
        key: &str,
        version_id: Option<VersionId>,
    ) -> impl Future<Output = Result<RecordMetadata, Error>> + Send;

    /// Lists complete records by key, then newest version first in history mode.
    /// Deleted versions are hidden; history includes remaining delete markers.
    /// The default limit is 1,000; zero is invalid. Pages are not snapshots.
    fn list(
        &self,
        prefix: &str,
        cursor: Option<&Cursor>,
        limit: Option<usize>,
        include_versions: bool,
    ) -> impl Future<Output = Result<PageResult, Error>> + Send;

    /// Creates a marker, or flags an explicit version without deleting its blob.
    /// Missing/already-deleted explicit versions succeed idempotently. Deleting
    /// the current version restores its newest non-deleted predecessor, including
    /// markers: a surviving marker keeps the current object absent.
    fn delete(
        &self,
        key: &str,
        version_id: Option<VersionId>,
    ) -> impl Future<Output = Result<DeleteResult, Error>> + Send;
}
